def parse(text, start):
    """ Return (parse tree, trivia) of text, from start rule, raise ParseError """
    parser = Parser(text)
    return parser.parse(start), parser.trivia


def matches(text, rule):
    """ True if whole text matches rule """
    try:
        Parser(text).parse(rule)
    except ParseError:
        return False
    return True
